def check(ctx):
    j = ctx.joint("finger_joint")
    if j is None:
        return None
    e = abs(j["effort"])
    if "max_seen" not in ctx.state:
        ctx.state["max_seen"] = e
        ctx.state["limit"] = ctx.value("max_clamp_effort")
    elif e > ctx.state["max_seen"]:
        ctx.state["max_seen"] = e
    if e > ctx.value("max_clamp_effort"):
        return {"value": e, "detail": "finger_joint effort exceeded max_clamp_effort"}
    return None

PART = "u_brown"

def check(ctx):
    if ctx.held_object() != PART:
        ctx.state["released"] = True
        return None
    if ctx.state.get("released"):
        return None
    t = ctx.transform("tcp", PART)["translation"]
    if "ref" not in ctx.state:
        ctx.state["ref"] = t
        ctx.state["max_dev"] = 0.0
        return None
    d = ctx.dist(t, ctx.state["ref"])
    if d > ctx.state["max_dev"]:
        ctx.state["max_dev"] = d
    if d > ctx.value("grasp_slip_tolerance_m"):
        return {"value": d, "detail": PART + " moved relative to tcp by " + str(round(d, 4)) + " m while held"}
    return None

